class Solution:
    def sumOfGoodSubsequences(self, nums):
        MOD = 10**9 + 7

        cnt = {}
        total = {}

        for x in nums:
            c = 1
            s = x

            if x - 1 in cnt:
                c = (c + cnt[x - 1]) % MOD
                s = (s + total[x - 1] + cnt[x - 1] * x) % MOD

            if x + 1 in cnt:
                c = (c + cnt[x + 1]) % MOD
                s = (s + total[x + 1] + cnt[x + 1] * x) % MOD

            cnt[x] = (cnt.get(x, 0) + c) % MOD
            total[x] = (total.get(x, 0) + s) % MOD

        return sum(total.values()) % MOD

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        ans = 0

        for a, b in [('N', 'E'), ('N', 'W'), ('S', 'E'), ('S', 'W')]:
            cur = 0
            changes = 0
            best = 0

            for ch in s:
                if ch == a or ch == b:
                    cur += 1
                elif changes < k:
                    cur += 1
                    changes += 1
                else:
                    cur -= 1

                if cur > best:
                    best = cur

            if best > ans:
                ans = best

        return ans

class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        def best_for_signs(pos_vertical, neg_vertical, pos_horizontal, neg_horizontal):
            ans = 0
            pv = nv = ph = nh = 0

            for i, ch in enumerate(s, 1):
                if ch == pos_vertical:
                    pv += 1
                elif ch == neg_vertical:
                    nv += 1
                elif ch == pos_horizontal:
                    ph += 1
                else:
                    nh += 1

                favorable = pv + ph
                unfavorable = nv + nh

                # For this sign choice, distance value is:
                # favorable - unfavorable + 2 * changes_used
                # where changes_used <= min(k, unfavorable)
                cur = favorable - unfavorable + 2 * min(k, unfavorable)

                # Also cannot exceed prefix length i
                if cur > i:
                    cur = i

                if cur > ans:
                    ans = cur
            return ans

        return max(
            best_for_signs('N', 'S', 'E', 'W'),  # x + y
            best_for_signs('N', 'S', 'W', 'E'),  # -x + y
            best_for_signs('S', 'N', 'E', 'W'),  # x - y
            best_for_signs('S', 'N', 'W', 'E')   # -x - y
        )

