class Solution:
    def countPairs(self, nums):
        def almost_equal(a, b):
            sa = str(a)
            sb = str(b)
            n = max(len(sa), len(sb))
            sa = sa.zfill(n)
            sb = sb.zfill(n)

            diff = []
            for i in range(n):
                if sa[i] != sb[i]:
                    diff.append(i)

            if len(diff) == 0:
                return True
            if len(diff) != 2:
                return False

            i, j = diff
            return sa[i] == sb[j] and sa[j] == sb[i]

        ans = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if almost_equal(nums[i], nums[j]):
                    ans += 1
        return ans

