class Solution:
    def countPairs(self, nums):
        def get_all_swaps(n):
            s = str(n)
            results = {int(s)}
            for i in range(len(s)):
                for j in range(i + 1, len(s)):
                    lst = list(s)
                    lst[i], lst[j] = lst[j], lst[i]
                    results.add(int(''.join(lst)))
            return results

        count = 0
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                swaps_i = get_all_swaps(nums[i])
                swaps_j = get_all_swaps(nums[j])
                # They are almost equal if we can swap digits in one of them to get the other
                if nums[j] in swaps_i or nums[i] in swaps_j:
                    count += 1
        return count
